<script setup lang="ts">
import {ref,onMounted,watch} from 'vue'
import type {components} from '../../shared/api'
import type {SessionClient} from '../auth/session'
type Reward=components['schemas']['RewardView'];type Grant=components['schemas']['GrantView']
const props=defineProps<{client:SessionClient;ru:boolean;me:components['schemas']['MemberView'];participants:components['schemas']['ParticipantView'][]}>()
const t=(en:string,ru:string)=>props.ru?ru:en
const rewards=ref<Reward[]>([]),grants=ref<Grant[]>([]),busy=ref(false),error=ref(''),editing=ref(false),selected=ref<Reward|null>(null),title=ref(''),description=ref(''),conditions=ref(''),granting=ref<Reward|null>(null),recipient=ref(''),key=ref(crypto.randomUUID())
const name=(id:string)=>id===props.me.id?props.me.display_name:props.participants.find(p=>p.id===id)?.display_name??t('Participant','Участник')
const label=(s:string)=>({offered:t('Offered','Предложено'),accepted:t('Accepted','Принято'),declined:t('Declined','Отклонено'),delivered:t('Delivered','Вручено'),cancelled:t('Cancelled','Отменено')}[s]??s)
const time=(s:string)=>new Intl.DateTimeFormat(props.ru?'ru-RU':'en-GB',{timeZone:props.me.timezone,year:'numeric',month:'short',day:'numeric',hour:'2-digit',minute:'2-digit',timeZoneName:'short'}).format(new Date(s))
async function load(){rewards.value=await props.client.get('/rewards');grants.value=await props.client.get('/reward-grants')}
async function run(fn:()=>Promise<void>){busy.value=true;error.value='';try{await fn()}catch(e){error.value=e instanceof Error?e.message:'NETWORK_ERROR'}finally{busy.value=false}}
onMounted(()=>run(load));watch(recipient,()=>key.value=crypto.randomUUID())
function startGrant(r:Reward){granting.value=r;recipient.value='';key.value=crypto.randomUUID()}
function edit(r:Reward|null){selected.value=r;title.value=r?.title??'';description.value=r?.description??'';conditions.value=r?.conditions??'';editing.value=true}
async function save(){await run(async()=>{const r=selected.value;await props.client.post(r?`/rewards/${r.id}/versions`:'/rewards',{title:title.value,description:description.value,conditions:conditions.value,...(r?{expected_version:r.revision}:{})});editing.value=false;await load()})}
async function grant(){await run(async()=>{if(!granting.value)return;await props.client.post('/reward-grants',{reward_version_id:granting.value.version_id,recipient_id:recipient.value,idempotency_key:key.value});granting.value=null;await load()})}
async function transition(g:Grant,action:string){await run(async()=>{await props.client.post(`/reward-grants/${g.id}/transitions`,{expected_version:g.revision,action});await load()})}
</script>
<template>
<section id="rewards" aria-labelledby="rewards-title"><div class="section-heading"><div><h2 id="rewards-title">{{t('Rewards','Награды')}}</h2><p class="muted">{{t('Offer care. Keep the choice.','Предложить заботу. Сохранить выбор.')}}</p></div><div><button :disabled="busy" @click="run(load)">{{t('Refresh rewards','Обновить награды')}}</button><button :disabled="busy||me.paused" @click="edit(null)">{{t('New reward','Новая награда')}}</button></div></div>
<p v-if="error" role="alert">{{error}} · {{t('Refresh to load the current state.','Обновите данные для актуального состояния.')}}</p>
<form v-if="editing" @submit.prevent="save"><label>{{t('Reward title','Название награды')}}<input v-model="title" required maxlength="200"></label><label>{{t('Reward description','Описание награды')}}<textarea v-model="description" required maxlength="10000" /></label><label>{{t('Reward conditions','Условия награды')}}<textarea v-model="conditions" maxlength="10000" /></label><button :disabled="busy||me.paused">{{t('Save reward','Сохранить награду')}}</button><button type="button" :disabled="busy" @click="editing=false">{{t('Cancel','Отмена')}}</button></form>
<h3>{{t('Your catalogue','Ваш каталог')}}</h3><p v-if="!rewards.length" class="muted">{{t('Create a reward before offering it or adding it to a ritual assignment.','Создайте награду перед выдачей или добавлением к назначению ритуала.')}}</p><article v-for="r in rewards" :key="r.id"><h4>{{r.title}}</h4><p>{{r.description}}</p><p>{{r.conditions}}</p><button :disabled="busy||me.paused" @click="startGrant(r)">{{t('Offer reward','Предложить награду')}}</button><button class="secondary" :disabled="busy||me.paused" @click="edit(r)">{{t('New reward version','Новая версия награды')}}</button></article>
<form v-if="granting" @submit.prevent="grant"><h3>{{granting.title}}</h3><label>{{t('Reward recipient','Получатель награды')}}<select v-model="recipient" required><option value="" disabled>—</option><option v-for="p in participants.filter(p=>p.id!==me.id)" :key="p.id" :value="p.id">{{p.display_name}}</option></select></label><p class="muted">{{t('A current direct rewards.grant agreement is required.','Требуется действующее прямое соглашение rewards.grant.')}}</p><button :disabled="busy||me.paused">{{t('Confirm reward offer','Подтвердить предложение награды')}}</button><button type="button" @click="granting=null">{{t('Cancel','Отмена')}}</button></form>
<h3>{{t('Your grants','Ваши выдачи')}}</h3><p v-if="!grants.length" class="muted">{{t('No reward offers yet.','Пока нет предложенных наград.')}}</p><article v-for="g in grants" :key="g.id" class="reward-grant"><div class="occurrence-heading"><h4>{{g.title}}</h4><span class="status-tag">{{label(g.status)}}</span></div><p>{{name(g.issuer_id)}} → {{name(g.recipient_id)}} · {{g.occurrence_id?t('Approved ritual','Одобренный ритуал'):t('Manual offer','Ручное предложение')}}</p><p>{{g.description}}</p><p>{{g.conditions}}</p><button v-if="g.recipient_id===me.id&&g.status==='offered'" :disabled="busy" @click="transition(g,'accept')">{{t('Accept reward','Принять награду')}}</button><button v-if="g.recipient_id===me.id&&g.status==='offered'" class="secondary" :disabled="busy" @click="transition(g,'decline')">{{t('Decline reward','Отклонить награду')}}</button><button v-if="g.issuer_id===me.id&&g.status==='accepted'" :disabled="busy||me.paused" @click="transition(g,'deliver')">{{t('Mark delivered','Отметить вручение')}}</button><button v-if="g.issuer_id===me.id&&['offered','accepted'].includes(g.status)" class="secondary" :disabled="busy||me.paused" @click="transition(g,'cancel')">{{t('Cancel reward','Отменить награду')}}</button><details><summary>{{t('Grant history','История выдачи')}}</summary><p v-for="h in g.history" :key="h.revision">{{label(h.status)}} · {{time(h.created_at)}}</p></details></article>
</section>
</template>
